from typing import List, Dict, Set, Tuple, Optional
import hashlib
import os


def hash_file(file_path: str) -> str:
    """Compute the SHA-256 hash of a file."""
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hasher.update(chunk)
    return hasher.hexdigest()


def snapshot_directory(directory_path: str) -> Dict[str, str]:
    """Snapshot a directory tree and compute file hashes."""
    files = {}
    for root, _, filenames in os.walk(directory_path):
        for filename in filenames:
            file_path = os.path.join(root, filename)
            relative_path = os.path.relpath(file_path, start=directory_path)
            try:
                files[relative_path] = hash_file(file_path)
            except PermissionError:
                print(f'Permission denied: {file_path}')
            except FileNotFoundError:
                print(f'File not found: {file_path}')
    return files


def compute_diff(old_snapshot: Dict[str, str], new_snapshot: Dict[str, str]) -> Tuple[Set[str], Set[str], Set[str], Dict[str, str]]:
    """Compute the diff between two snapshots."""
    old_files = set(old_snapshot.keys())
    new_files = set(new_snapshot.keys())
    added = new_files - old_files
    removed = old_files - new_files
    common_files = old_files & new_files
    modified = {file: (old_snapshot[file], new_snapshot[file]) for file in common_files if old_snapshot[file] != new_snapshot[file]}
    renames = {}
    for old_file, new_file in zip(sorted(old_files), sorted(new_files)):
        if old_file == new_file:
            continue
        if hash_file(os.path.join(directory_path, old_file)) == hash_file(os.path.join(directory_path, new_file)):
            renames[old_file] = new_file
    return (added, removed, modified, renames)


def main():
    """Main."""
    directory_path = '/path/to/large/directory'
    snapshot1 = snapshot_directory(directory_path)
    import time
    time.sleep(5)
    snapshot2 = snapshot_directory(directory_path)
    added, removed, modified, renames = compute_diff(snapshot1, snapshot2)
    print('Added:', added)
    print('Removed:', removed)
    print('Modified:', modified)
    print('Renames:', renames)


if __name__ == '__main__':
    main()
